"""Daily PSP settlement reconciliation matching engine."""

from __future__ import annotations

import re
from datetime import date, datetime, timedelta
from zoneinfo import ZoneInfo

_BUSINESS_TZ = ZoneInfo("America/New_York")
_CUTOFF_HOUR = 17
_IGNORED_TYPE = "FEE"
_CHARGEBACK = "CHARGEBACK"
_CHARGEBACK_REVERSAL = "CHARGEBACK_REVERSAL"

_CURRENCIES_BY_EXPONENT = {
    0: "BIF CLP DJF GNF ISK JPY KMF KRW PYG RWF UGX UYI VND VUV XAF XOF XPF",
    2: (
        "AED AFN ALL AMD ANG AOA ARS AUD AWG AZN BAM BBD BDT BGN BMD BND BOB "
        "BOV BRL BSD BTN BWP BYN BZD CAD CDF CHE CHF CHW CNY COP COU CRC CUC "
        "CUP CVE CZK DKK DOP DZD EGP ERN ETB EUR FJD FKP GBP GEL GHS GIP GMD "
        "GTQ GYD HKD HNL HRK HTG HUF IDR ILS INR IRR JMD KES KGS KHR KPW KYD "
        "KZT LAK LBP LKR LRD LSL MAD MDL MGA MKD MMK MNT MOP MRU MUR MVR MWK "
        "MXN MXV MYR MZN NAD NGN NIO NOK NPR NZD PAB PEN PGK PHP PKR PLN QAR "
        "RON RSD RUB SAR SBD SCR SDG SEK SGD SHP SLE SLL SOS SRD SSP STN SVC "
        "SYP SZL THB TJS TMT TOP TRY TTD TWD TZS UAH USD USN UYU UZS VED VES "
        "WST XCD XCG YER ZAR ZMW ZWG ZWL"
    ),
    3: "BHD IQD JOD KWD LYD OMR TND",
    4: "CLF UYW",
}
_MINOR_UNIT_EXPONENT = {
    code: exponent
    for exponent, codes in _CURRENCIES_BY_EXPONENT.items()
    for code in codes.split()
}

_AMOUNT_RE = re.compile(
    r"(?P<open>\()?"
    r"(?P<whole>[0-9]{1,3}(?:,[0-9]{3})+|[0-9]+)"
    r"(?:\.(?P<fraction>[0-9]+))?"
    r"(?P<close>\))?"
)

GroupKey = tuple[str, str, str]  # (psp_ref, type, currency)
Group = tuple[int, date]  # (amount_minor, latest business date)


def _to_minor_units(amount: str, currency: str) -> int:
    """Convert processor amount text to integer minor units without floats.

    Malformed text, unknown currencies and any non-zero precision beyond the
    currency's ISO 4217 exponent raise ValueError, so a bad file cannot
    produce a silently wrong figure.
    """
    exponent = _MINOR_UNIT_EXPONENT.get(currency)
    if exponent is None:
        raise ValueError(f"Unknown ISO 4217 minor unit for currency {currency!r}")

    match = _AMOUNT_RE.fullmatch(amount.strip())
    if match is None or bool(match["open"]) != bool(match["close"]):
        raise ValueError(f"Malformed settlement amount {amount!r}")

    whole = match["whole"].replace(",", "")
    fraction = match["fraction"] or ""
    if fraction[exponent:].strip("0"):
        raise ValueError(
            f"Amount {amount!r} exceeds the precision of {currency} "
            f"({exponent} decimal places)"
        )

    minor = int(whole + fraction[:exponent].ljust(exponent, "0"))
    return -minor if match["open"] else minor


def _business_date(event_time: str, holidays: set[date]) -> date:
    """Derive the business date for a UTC event timestamp."""
    text = event_time.strip()
    # datetime.fromisoformat() does not accept a "Z" suffix before Python 3.11.
    if text.endswith("Z"):
        text = text[:-1] + "+00:00"

    instant = datetime.fromisoformat(text)
    if instant.tzinfo is None:
        raise ValueError(f"event_time has no UTC offset: {event_time!r}")

    local = instant.astimezone(_BUSINESS_TZ)
    day = local.date()
    if local.hour >= _CUTOFF_HOUR:
        day += timedelta(days=1)
    while day.weekday() >= 5 or day in holidays:
        day += timedelta(days=1)
    return day


def _effective_lines(settlement_lines: list[dict]) -> list[dict]:
    """Keep only the lines from the highest file_seq of each batch.

    This must run before FEE filtering: a resend containing only FEE lines
    still voids every lower file_seq of that batch.
    """
    highest_seq: dict[str, int] = {}
    for line in settlement_lines:
        batch_id = line["batch_id"]
        seq = int(line["file_seq"])
        if batch_id not in highest_seq or seq > highest_seq[batch_id]:
            highest_seq[batch_id] = seq

    return [
        line
        for line in settlement_lines
        if int(line["file_seq"]) == highest_seq[line["batch_id"]]
    ]


def _add_to_group(
    groups: dict[GroupKey, Group], key: GroupKey, amount: int, day: date
) -> None:
    if key in groups:
        total, latest = groups[key]
        groups[key] = (total + amount, max(latest, day))
    else:
        groups[key] = (amount, day)


def _group_ledger(ledger_rows: list[dict]) -> dict[GroupKey, Group]:
    groups: dict[GroupKey, Group] = {}
    for row in ledger_rows:
        if row["type"] == _IGNORED_TYPE:
            continue
        key = (row["psp_ref"], row["type"], row["currency"])
        day = date.fromisoformat(row["business_date"])
        _add_to_group(groups, key, row["amount_minor"], day)
    return groups


def _group_settlement(
    settlement_lines: list[dict], holidays: set[date]
) -> dict[GroupKey, Group]:
    groups: dict[GroupKey, Group] = {}
    for line in _effective_lines(settlement_lines):
        if line["line_type"] == _IGNORED_TYPE:
            continue
        currency = line["currency"]
        key = (line["psp_ref"], line["line_type"], currency)
        amount = _to_minor_units(line["amount"], currency)
        day = _business_date(line["event_time"], holidays)
        _add_to_group(groups, key, amount, day)
    return groups


def _net_chargebacks(
    settlement: dict[GroupKey, Group], ledger: dict[GroupKey, Group]
) -> None:
    """Remove offsetting settlement chargeback pairs the ledger never saw."""
    for psp_ref, line_type, currency in list(settlement):
        if line_type != _CHARGEBACK:
            continue

        chargeback_key = (psp_ref, _CHARGEBACK, currency)
        reversal_key = (psp_ref, _CHARGEBACK_REVERSAL, currency)
        if reversal_key not in settlement:
            continue
        if chargeback_key in ledger or reversal_key in ledger:
            continue
        if settlement[chargeback_key][0] + settlement[reversal_key][0] != 0:
            continue

        del settlement[chargeback_key]
        del settlement[reversal_key]


def _classify(
    settlement_group: Group | None, ledger_group: Group | None
) -> tuple[str, int] | None:
    """Return (break, delta_minor) for a group key, or None if it matches."""
    if ledger_group is None:
        return "MISSING_IN_LEDGER", settlement_group[0]
    if settlement_group is None:
        return "MISSING_IN_SETTLEMENT", -ledger_group[0]

    settlement_amount, settlement_date = settlement_group
    ledger_amount, ledger_date = ledger_group
    if settlement_amount != ledger_amount:
        return "AMOUNT_MISMATCH", settlement_amount - ledger_amount
    if settlement_date != ledger_date:
        return "TIMING", 0
    return None


def reconcile(
    ledger_rows: list[dict], settlement_lines: list[dict], holidays: list[str]
) -> list[dict]:
    """Compare ledger and settlement data and return the sorted break list."""
    holiday_dates = {date.fromisoformat(holiday) for holiday in holidays}

    ledger = _group_ledger(ledger_rows)
    settlement = _group_settlement(settlement_lines, holiday_dates)
    _net_chargebacks(settlement, ledger)

    breaks: list[dict] = []
    for key in sorted(ledger.keys() | settlement.keys()):
        result = _classify(settlement.get(key), ledger.get(key))
        if result is None:
            continue
        psp_ref, type_, currency = key
        break_name, delta_minor = result
        breaks.append(
            {
                "psp_ref": psp_ref,
                "type": type_,
                "currency": currency,
                "break": break_name,
                "delta_minor": delta_minor,
            }
        )
    return breaks
